import { NextRequest, NextResponse } from 'next/server'
import { Types } from 'mongoose'
import { getAdminDashboardAccess } from '@/lib/admin-access'
import { connectDB } from '@/lib/db'
import { Vendor } from '@/models/vendor'
import { isVendorServiceType, normalizeVendorName, validateVendorLocations } from '@/lib/vendors'
async function admin(request: NextRequest) { return getAdminDashboardAccess(request.headers) }
export async function PATCH(request: NextRequest, { params }: { params: Promise<{ id: string }> }) { const access = await admin(request); const { id } = await params; if (!access) return NextResponse.json({ error: 'Forbidden' }, { status: 403 }); if (!Types.ObjectId.isValid(id)) return NextResponse.json({ error: 'Invalid vendor.' }, { status: 400 }); try { await connectDB(); const current = await Vendor.findById(id); if (!current) return NextResponse.json({ error: 'Vendor not found.' }, { status: 404 }); const body = await request.json(), name = body.name === undefined ? current.name : String(body.name).trim(), serviceType = body.serviceType === undefined ? current.serviceType : String(body.serviceType); if (!name || !isVendorServiceType(serviceType)) return NextResponse.json({ error: 'Enter a vendor name and valid service type.' }, { status: 400 }); const locations = await validateVendorLocations(body.pickupParentLocationId === undefined ? String(current.pickupParentLocationId || '') : body.pickupParentLocationId || null, body.pickupExactLocationId === undefined ? String(current.pickupExactLocationId || '') : body.pickupExactLocationId || null); Object.assign(current, { name, normalizedName: normalizeVendorName(name), serviceType, pickupParentLocationId: locations.parent?._id || null, pickupExactLocationId: locations.exact?._id || null, active: body.active === undefined ? current.active : Boolean(body.active), businessId: body.businessId === undefined ? current.businessId : body.businessId || null, updatedBy: access.userId }); await current.save(); return NextResponse.json({ vendor: current }) } catch (error) { return NextResponse.json({ error: error instanceof Error ? error.message : 'Unable to update vendor.' }, { status: 400 }) } }
